#!/bin/sh
# size-cal.sh - build, measure and image-inspect the binary-size calibration corpus (Docker builds only).
# usage: size-cal.sh tools [flavor]
#        size-cal.sh build CRATE NAME [--env "K=V K=V"] [--flavor musl|gnu] [--no-cache] [--attrib] [--gitsha S] [--ver V]
#        size-cal.sh measure CRATE NAME
#        size-cal.sh image CRATE
#        size-cal.sh --help | --build | --version
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'binary-size-calibration/size-cal.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'size-cal.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  cat <<'USAGE'
usage: size-cal.sh tools [musl|gnu]      build the tools image (bsc:tools or bsc:tools-gnu), print toolchain and tool versions
       size-cal.sh build CRATE NAME      docker build the release binary of CRATE (router|tracker) into var/size-out/CRATE/NAME/
       size-cal.sh measure CRATE NAME    print one TSV row for that binary (host binutils, gzip, zstd, sha256)
       size-cal.sh image CRATE           build the crate's own Dockerfile as bsc:CRATE-img, print inspect and history
       size-cal.sh --help | --build | --version
build options: --env "K=V K=V"  CARGO_PROFILE_RELEASE_* overrides (empty = the fleet profile)
               --flavor F       musl (default, the fleet recipe) or gnu (Debian toolchain, glibc)
               --no-cache       docker build --no-cache
               --attrib         also run cargo-bloat and bloaty, results in var/size-out/CRATE/NAME/attr/ (musl only)
               --gitsha S       GIT_SHA build arg (default unknown)
               --ver V          build a scratch copy of the crate with only its package version string set to V
The corpus is read from var/size-corpus/router/router/gateway and var/size-corpus/tracker/initiative_tracker
(git archive extracts, see notes.md). Fleet repos are never modified; images use the bsc: tag prefix.
Measure columns: crate name sha256 file_bytes size_A_sum text_bytes load_filesz load_memsz gzip9 zstd19.
USAGE
  exit 0
fi
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
build_id() {
  d=$(git --no-optional-locks -C "$HERE" rev-parse --show-toplevel 2>/dev/null) || d=
  [ -n "$d" ] || { echo unknown; return; }
  sha=$(git --no-optional-locks -C "$d" log -1 --format=%H -- "$d" 2>/dev/null) || sha=
  [ -n "$sha" ] || { echo unknown; return; }
  if [ -n "$(git --no-optional-locks -C "$d" status --porcelain --untracked-files=no -- "$d" 2>/dev/null)" ]; then echo "$sha-dirty"; else echo "$sha"; fi
}
case ${1:-} in
  --build|--version) build_id; exit 0 ;;
esac
ROOT=$(cd "$HERE/.." && pwd)
CORPUS=$ROOT/var/size-corpus
OUT=$ROOT/var/size-out
die() { echo "size-cal.sh: $*" >&2; exit 2; }

crate_vars() {
  case $1 in
    router) CTX=$CORPUS/router/router/gateway; PKG_ARGS="--bin inference-router"; BIN=inference-router
            VTOML=Cargo.toml; VPKG=inference-router ;;
    tracker) CTX=$CORPUS/tracker/initiative_tracker; PKG_ARGS="-p initiative-tracker-server --bin initiative-tracker"; BIN=initiative-tracker
            VTOML=crates/server/Cargo.toml; VPKG=initiative-tracker-server ;;
    *) die "unknown crate '$1' (router|tracker)" ;;
  esac
  [ -d "$CTX" ] || die "corpus $CTX missing (extract it first, see notes.md)"
}

mode=${1:?mode (try --help)}
shift
case $mode in
  tools)
    fl=${1:-musl}
    case $fl in
      musl) tag=bsc:tools ;;
      gnu) tag=bsc:tools-gnu ;;
      *) die "flavor must be musl or gnu" ;;
    esac
    crate_vars router
    docker build -q -t "$tag" --build-arg FLAVOR="$fl" --target base -f "$HERE/Dockerfile" "$CTX" >/dev/null
    docker run --rm "$tag" sh -c 'rustc -V; cargo -V; cargo auditable --version; gcc --version | head -1; ldd --version 2>&1 | head -1
      if command -v apk >/dev/null; then apk list -I bloaty cargo-bloat binutils musl-dev 2>/dev/null; bloaty --version | head -1; cargo bloat --version; fi'
    ;;
  build)
    crate=${1:?crate}; name=${2:?name}; shift 2
    crate_vars "$crate"
    envs=; fl=musl; nocache=; attrib=; sha=unknown; ver=
    while [ $# -gt 0 ]; do
      case $1 in
        --env) envs=${2?}; shift 2 ;;
        --flavor) fl=${2?}; shift 2 ;;
        --no-cache) nocache=--no-cache; shift ;;
        --attrib) attrib=1; shift ;;
        --gitsha) sha=${2?}; shift 2 ;;
        --ver) ver=${2?}; shift 2 ;;
        *) die "unknown option '$1'" ;;
      esac
    done
    case $fl in musl|gnu) ;; *) die "flavor must be musl or gnu" ;; esac
    [ -z "$attrib" ] || [ "$fl" = musl ] || die "--attrib needs the musl flavor"
    ctx=$CTX
    if [ -n "$ver" ]; then
      ctx=$ROOT/var/size-ctx/$crate-$name
      rm -rf "$ctx"; mkdir -p "$ctx"; cp -a "$CTX/." "$ctx/"
      sed -i '0,/^version = ".*"$/s//version = "'"$ver"'"/' "$ctx/$VTOML"
      sed -i '/^name = "'"$VPKG"'"$/{n;s/^version = .*/version = "'"$ver"'"/}' "$ctx/Cargo.lock"
    fi
    dest=$OUT/$crate/$name
    rm -rf "$dest"; mkdir -p "$dest"
    set -- --build-arg FLAVOR="$fl" --build-arg GIT_SHA="$sha" --build-arg BUILD_ENVS="$envs" \
      --build-arg PKG_ARGS="$PKG_ARGS" --build-arg BIN="$BIN" -f "$HERE/Dockerfile"
    # shellcheck disable=SC2086
    docker build $nocache "$@" --target out --output "type=local,dest=$dest" "$ctx" >"$dest.log" 2>&1 || { tail -20 "$dest.log" >&2; die "build failed ($dest.log)"; }
    if [ -n "$attrib" ]; then
      mkdir -p "$dest/attr"
      docker build "$@" --target attrout --output "type=local,dest=$dest/attr" "$ctx" >"$dest.attr.log" 2>&1 || { tail -20 "$dest.attr.log" >&2; die "attrib failed ($dest.attr.log)"; }
    fi
    echo "built $dest/$BIN"
    ;;
  measure)
    crate=${1:?crate}; name=${2:?name}
    crate_vars "$crate"
    f=$OUT/$crate/$name/$BIN
    [ -f "$f" ] || die "$f missing"
    sha=$(sha256sum "$f" | cut -d' ' -f1)
    fb=$(stat -c %s "$f")
    sa=$(size -A "$f" | awk '$1=="Total"{print $2}')
    tx=$(size -A "$f" | awk '$1==".text"{print $2}')
    ld=$(readelf -lW "$f" | awk '$1=="LOAD"{print $5, $6}' | { fs=0; ms=0; while read -r a b; do fs=$((fs + a)); ms=$((ms + b)); done; printf "%d\t%d" "$fs" "$ms"; })
    gz=$(gzip -9 -c "$f" | wc -c)
    zs=$(zstd -19 -c -q "$f" | wc -c)
    printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$crate" "$name" "$sha" "$fb" "$sa" "$tx" "$ld" "$gz" "$zs"
    ;;
  image)
    crate=${1:?crate}
    crate_vars "$crate"
    tag=bsc:$crate-img
    docker build -q -t "$tag" --build-arg GIT_SHA=unknown -f "$CTX/Dockerfile" "$CTX" >/dev/null
    docker image inspect "$tag" --format 'image_id={{.Id}} size_bytes={{.Size}} layers={{len .RootFS.Layers}}'
    docker history --no-trunc --human=false --format '{{.Size}}\t{{.CreatedBy}}' "$tag"
    ;;
  *) die "unknown mode '$mode' (try --help)" ;;
esac
